/* The blog editor (/admin/blog, round 45). blog_posts gains a draft copy (draft_content, draft_meta, draft_saved_at): the editor saves into it while a post is live, and the live columns change only on Update. Also author_id, canonical_url, og_image_url, cover_alt, noindex, tags (text[], GIN indexed), and author_name when it is missing. The updated_at trigger is rebuilt to move only when something a reader sees changes, so a view count or a draft save no longer changes a post's modified date or its sitemap lastmod. A published post with no date gets its created_at. New tables: blog_categories (seeded with the blog's eight categories), blog_authors (seeded from the bylines already on posts, which are linked to them), blog_post_revisions (a copy at every manual save and publish, about 50 kept per post), blog_redirects (an old slug and the slug it moved to, followed with a 308) and blog_snippets (reusable blocks). Row level security on every table: the public key reads categories, authors and redirects, and only live posts (published, and the date reached) without their draft columns; revisions and snippets are server only. Safe to run again. */
ALTER TABLE public.blog_posts ADD COLUMN IF NOT EXISTS author_name text, ADD COLUMN IF NOT EXISTS draft_content jsonb, ADD COLUMN IF NOT EXISTS draft_meta jsonb, ADD COLUMN IF NOT EXISTS draft_saved_at timestamptz, ADD COLUMN IF NOT EXISTS canonical_url text, ADD COLUMN IF NOT EXISTS og_image_url text, ADD COLUMN IF NOT EXISTS cover_alt text, ADD COLUMN IF NOT EXISTS noindex boolean NOT NULL DEFAULT false, ADD COLUMN IF NOT EXISTS tags text[] NOT NULL DEFAULT '{}';
CREATE TABLE IF NOT EXISTS public.blog_categories (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), slug text NOT NULL UNIQUE CHECK (slug ~ '^[a-z0-9]([a-z0-9-]{0,78}[a-z0-9])?$'), name text NOT NULL UNIQUE CHECK (char_length(name) BETWEEN 1 AND 80), description text NOT NULL DEFAULT '' CHECK (char_length(description) <= 500), sort_order integer NOT NULL DEFAULT 0, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
INSERT INTO public.blog_categories (slug, name, description, sort_order) VALUES ('getting-started', 'Getting Started', 'Everything you need to launch your first digital product store, from choosing what to sell to getting your first sale.', 1), ('creator-tips', 'Creator Tips', 'Practical advice to help you create, market, and sell digital products more effectively.', 2), ('growth', 'Growth', 'Strategies to grow your audience, reach new customers, and scale your creator business.', 3), ('strategy', 'Strategy', 'Business frameworks and pricing tactics for building a sustainable creator income.', 4), ('product-updates', 'Product Updates', 'The latest features, improvements, and news straight from the Storelib team.', 5), ('case-studies', 'Case Studies', 'Real stories from creators who''ve built successful businesses on Storelib.', 6), ('tutorials', 'Tutorials', 'Step-by-step guides to get the most out of every Storelib feature.', 7), ('announcements', 'Announcements', 'Important news and milestones from the Storelib team.', 8) ON CONFLICT DO NOTHING;
CREATE TABLE IF NOT EXISTS public.blog_authors (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), slug text NOT NULL UNIQUE CHECK (slug ~ '^[a-z0-9]([a-z0-9-]{0,78}[a-z0-9])?$'), name text NOT NULL CHECK (char_length(name) BETWEEN 1 AND 80), role text NOT NULL DEFAULT '' CHECK (char_length(role) <= 80), bio text NOT NULL DEFAULT '' CHECK (char_length(bio) <= 1000), avatar_url text, links jsonb NOT NULL DEFAULT '[]'::jsonb, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
ALTER TABLE public.blog_posts ADD COLUMN IF NOT EXISTS author_id uuid REFERENCES public.blog_authors(id) ON DELETE SET NULL;
CREATE OR REPLACE FUNCTION public.update_blog_post_updated_at() RETURNS trigger LANGUAGE plpgsql AS $f$ BEGIN IF coalesce(current_setting('storelib.blog_keep_updated_at', true), '') = 'on' THEN NEW.updated_at = OLD.updated_at; RETURN NEW; END IF; IF (to_jsonb(NEW) - ARRAY['views', 'updated_at', 'draft_content', 'draft_meta', 'draft_saved_at']) IS DISTINCT FROM (to_jsonb(OLD) - ARRAY['views', 'updated_at', 'draft_content', 'draft_meta', 'draft_saved_at']) THEN NEW.updated_at = now(); ELSE NEW.updated_at = OLD.updated_at; END IF; RETURN NEW; END $f$;
DROP TRIGGER IF EXISTS blog_posts_updated_at ON public.blog_posts;
CREATE TRIGGER blog_posts_updated_at BEFORE UPDATE ON public.blog_posts FOR EACH ROW EXECUTE FUNCTION public.update_blog_post_updated_at();
SELECT set_config('storelib.blog_keep_updated_at', 'on', true);
INSERT INTO public.blog_authors (slug, name, role) SELECT DISTINCT ON (s.slug) s.slug, s.name, s.role FROM (SELECT trim(both '-' from regexp_replace(lower(split_part(b.byline, ' - ', 1)), '[^a-z0-9]+', '-', 'g')) AS slug, left(trim(split_part(b.byline, ' - ', 1)), 80) AS name, left(trim(CASE WHEN position(' - ' in b.byline) > 0 THEN substr(b.byline, position(' - ' in b.byline) + 3) ELSE '' END), 80) AS role FROM (SELECT DISTINCT coalesce(nullif(trim(to_jsonb(p) ->> 'author_name'), ''), nullif(trim(to_jsonb(p) ->> 'author'), '')) AS byline FROM public.blog_posts p) b WHERE b.byline IS NOT NULL) s WHERE s.slug ~ '^[a-z0-9]([a-z0-9-]{0,78}[a-z0-9])?$' AND s.name <> '' ORDER BY s.slug, s.role DESC ON CONFLICT (slug) DO NOTHING;
UPDATE public.blog_posts p SET author_id = a.id FROM public.blog_authors a WHERE p.author_id IS NULL AND a.slug = trim(both '-' from regexp_replace(lower(split_part(coalesce(nullif(trim(to_jsonb(p) ->> 'author_name'), ''), nullif(trim(to_jsonb(p) ->> 'author'), ''), ''), ' - ', 1)), '[^a-z0-9]+', '-', 'g'));
UPDATE public.blog_posts SET published_at = coalesce(created_at, now()) WHERE is_published = true AND published_at IS NULL;
SELECT set_config('storelib.blog_keep_updated_at', 'off', true);
CREATE INDEX IF NOT EXISTS blog_posts_tags_idx ON public.blog_posts USING gin (tags);
CREATE INDEX IF NOT EXISTS blog_posts_author_idx ON public.blog_posts (author_id) WHERE author_id IS NOT NULL;
CREATE INDEX IF NOT EXISTS blog_posts_category_idx ON public.blog_posts (category);
CREATE TABLE IF NOT EXISTS public.blog_post_revisions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), post_id uuid NOT NULL REFERENCES public.blog_posts(id) ON DELETE CASCADE, kind text NOT NULL DEFAULT 'save' CHECK (kind IN ('save', 'publish', 'update', 'unpublish', 'schedule', 'restore')), title text NOT NULL DEFAULT '', content jsonb NOT NULL DEFAULT '[]'::jsonb, meta jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now(), created_by text);
CREATE INDEX IF NOT EXISTS blog_post_revisions_post_idx ON public.blog_post_revisions (post_id, created_at DESC);
CREATE TABLE IF NOT EXISTS public.blog_redirects (from_slug text PRIMARY KEY CHECK (char_length(from_slug) BETWEEN 1 AND 200), to_slug text NOT NULL CHECK (char_length(to_slug) BETWEEN 1 AND 200), post_id uuid REFERENCES public.blog_posts(id) ON DELETE CASCADE, created_at timestamptz NOT NULL DEFAULT now(), CHECK (from_slug <> to_slug));
CREATE INDEX IF NOT EXISTS blog_redirects_to_idx ON public.blog_redirects (to_slug);
CREATE TABLE IF NOT EXISTS public.blog_snippets (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL CHECK (char_length(name) BETWEEN 1 AND 120), blocks jsonb NOT NULL DEFAULT '[]'::jsonb, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
ALTER TABLE public.blog_categories ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.blog_authors ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.blog_post_revisions ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.blog_redirects ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.blog_snippets ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.blog_posts ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS blog_categories_public_read ON public.blog_categories;
CREATE POLICY blog_categories_public_read ON public.blog_categories FOR SELECT TO anon, authenticated USING (true);
DROP POLICY IF EXISTS blog_authors_public_read ON public.blog_authors;
CREATE POLICY blog_authors_public_read ON public.blog_authors FOR SELECT TO anon, authenticated USING (true);
DROP POLICY IF EXISTS blog_redirects_public_read ON public.blog_redirects;
CREATE POLICY blog_redirects_public_read ON public.blog_redirects FOR SELECT TO anon, authenticated USING (true);
DROP POLICY IF EXISTS "blog_posts_public_read" ON public.blog_posts;
CREATE POLICY "blog_posts_public_read" ON public.blog_posts FOR SELECT TO anon, authenticated USING (is_published = true AND (published_at IS NULL OR published_at <= now()));
REVOKE ALL ON public.blog_categories, public.blog_authors, public.blog_redirects FROM anon, authenticated;
GRANT SELECT ON public.blog_categories, public.blog_authors, public.blog_redirects TO anon, authenticated;
REVOKE ALL ON public.blog_post_revisions, public.blog_snippets FROM anon, authenticated;
GRANT SELECT, INSERT, UPDATE, DELETE ON public.blog_categories, public.blog_authors, public.blog_post_revisions, public.blog_redirects, public.blog_snippets TO service_role;
DO $do$ DECLARE cols text; BEGIN SELECT string_agg(quote_ident(column_name), ', ' ORDER BY ordinal_position) INTO cols FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'blog_posts' AND column_name NOT IN ('draft_content', 'draft_meta', 'draft_saved_at'); REVOKE SELECT ON public.blog_posts FROM anon, authenticated; EXECUTE format('GRANT SELECT (%s) ON public.blog_posts TO anon, authenticated', cols); END $do$;
notify pgrst, 'reload schema';
